import java.util.Iterator;
import java.util.List;
import java.util.Random;

/**
 * A simple model of a Hunter.
 * Hunters age, move, hunt lions, and die.
 * Hunters can bring other hunters after 898 steps to increse the hunter population.
 *
 * @version 2022.03.01
 */
public class Hunter extends Actor

{
    // Characteristics shared by all Hunters.
    private static final int MAX_AGE = 1000;
    private static final int SHOTS = 2; 
    /**
     * Create a Hunter. A hunter is created as an adult (age 50).
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Hunter(Field field, Location location)
    {
        super(field, location);
        setAge(50);
        setGrowthLevel(0);
    }

    /**
     * This is what the Hunter does most of the time: it hunts
     * lions during the night. In the process, it might die of old age.
     * 
     * @param newHunters A list to return new Hunters.
     * @param simulator The simulator.
     */
    public void act(List<Actor> newHunters,Simulator simulator){
        incrementAge(simulator.getSteps());
        if(!simulator.isDay()){
            if(isActive() ) {
                switch(simulator.getWeather()){
                    case RAINY:
                        hunt(0.7);
                        break;
                    case FOGGY:
                        hunt(0.4);
                        break;
                    default:
                        hunt(getRandom().nextDouble());
                        break;
                }
                Field field = getField();
                Location newLocation = field.freeAdjacentLocation(getLocation());
                if(newLocation != null) {
                    setLocation(newLocation);
                } 
                //hunter number increases as there are more hunters in the area who want to hunt.
                if (simulator.getSteps() % 898 ==  0){
                    List<Location> free = field.getFreeAdjacentLocations(getLocation());
                    if(free.size() > 0) {
                        Location loc = free.remove(0);
                        Hunter hunter = new Hunter(field, loc);
                        newHunters.add(hunter);
                    }
                }
            }
        }
    }

    /**
     * This determine how the hunter hunts nearby lions
     * The hunter has 2 shots.
     * @param probability The probability the hunting is successful.
     */
    private void hunt(double probability){
        if(getRandom().nextDouble() < probability){
            Field field = getField();
            List<Location> adjacent = field.adjacentLocations(getLocation());
            Iterator<Location> it = adjacent.iterator();
            for(int i = 0; i< SHOTS; i++){
                Location where = it.next();
                Object animal = field.getObjectAt(where);
                if( animal != null && (animal instanceof Lion  || animal instanceof Cheetah)){
                    Animal currentAnimal = (Animal) animal;
                    if(currentAnimal.isActive()) { 
                        currentAnimal.setDead();
                        break;
                    }
                }
            }
        }
    }

    /**
     * Gets the max age of a hunter.
     * @return int. Max age of the hunter.
     */
    protected int getMaxAge(){
        return MAX_AGE;
    }
}

import java.awt.Color;
import java.util.HashMap;

/**
 * This class collects and provides some statistical data on the state 
 * of a field. It is flexible: it will create and maintain a counter 
 * for any class of object that is found within the field.
 *
 * @version 2022.03.01
 */
public class FieldStats
{
    // Counters for each type of entity (jaguar, gazelle, etc.) in the simulation.
    private HashMap<Class, Counter> counters;
    // Whether the counters are currently up to date.
    private boolean countsValid;

    /**
     * Construct a FieldStats object.
     */
    public FieldStats()
    {
        // Set up a collection for counters for each type of animal that
        // we might find
        counters = new HashMap<>();
        countsValid = true;
    }

    /**
     * Get details of what is in the field.
     * @param field The field currently occupied.
     * @param simulator. The current simulator the simulation is being run on.
     * @return A string listing what is in the field.
     */
    public String getPopulationDetails(Field field, Simulator simulator)
    {
        StringBuffer buffer = new StringBuffer();
        if(!countsValid) {
            generateCounts(field, simulator);
        }
        for(Class key : counters.keySet()) {
            Counter info = counters.get(key);
            buffer.append(info.getName());
            buffer.append(": ");
            buffer.append(info.getCount());
            buffer.append(' ');
        }
        return buffer.toString();
    }

    /**
     * Invalidate the current set of statistics; reset all 
     * counts to zero.
     */
    public void reset()
    {
        countsValid = false;
        for(Class key : counters.keySet()) {
            Counter count = counters.get(key);
            count.reset();
        }
    }

    /**
     * Increment the count for one class of actor.
     * @param actor The object of animal to increment.
     * @param simulator. The current simulator the simulation is being run on.
     */
    public void incrementCount(Object actor, Simulator simulator)
    {
        Class animalClass = actor.getClass();
        Counter count = counters.get(animalClass);
        if(count == null) {
            // We do not have a counter for this species yet.
            // Create one.
            count = new Counter(animalClass.getName());
            counters.put(animalClass, count);
        }
        count.increment();
        if (simulator.getSteps() != 0){
            if(actor instanceof Grass){
                count.setCount(simulator.getNoOfGrass());
            }
        }
    }

    /**
     * Indicate that an actor count has been completed.
     */
    public void countFinished()
    {
        countsValid = true;
    }

    /**
     * Determine whether the simulation is still viable.
     * I.e., should it continue to run.
     * @param field The field currently occupied.
     * @param simulator The current simulator the simulation is being run on.
     * @return true If there is more than one species alive.
     */
    public boolean isViable(Field field, Simulator simulator)
    {
        // How many counts are non-zero.
        int nonZero = 0;
        if(!countsValid) {
            generateCounts(field, simulator);
        }
        for(Class key : counters.keySet()) {
            Counter info = counters.get(key);
            if(info.getCount() > 0) {
                nonZero++;
            }
        }
        return nonZero > 1;
    }

    /**
     * Generate counts of the number of all animals.
     * These are not kept up to date as all animals
     * are placed in the field, but only when a request
     * is made for the information.
     * @param field The field to generate the stats for.
     * @param simulator The current simulator the simulation is being run on.
     */
    private void generateCounts(Field field, Simulator simulator)
    {
        reset();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    incrementCount(animal, simulator);
                }
            }
        }
        countsValid = true;
    }
}

