 60	    public Simulator(int depth, int width)
 61	    {
 62	        if(width <= 0 || depth <= 0) {
 63	            System.out.println("The dimensions must be greater than zero.");
 64	            System.out.println("Using default values.");
 65	            depth = DEFAULT_DEPTH;
 66	            width = DEFAULT_WIDTH;
