184	    {
185	        //Random rand = Randomizer.getRandom();
186	        field.clear();
187	        for(int row = 0; row < field.getDepth(); row++) {
188	            for(int col = 0; col < field.getWidth(); col++) {
189	                if(rand.nextDouble() <= LION_CREATION_PROBABILITY) {
190	                    Location location = new Location(row, col);
191	                    Animal lion = new Lion(true, field, location);
192	                    animals.add(lion);
193	                }
194	                else if(rand.nextDouble() <= CHEETAH_CREATION_PROBABILITY) {
195	                    Location location = new Location(row, col);
