197	                    animals.add(cheetah);
198	                }
199	                else if(rand.nextDouble() <= GAZELLE_CREATION_PROBABILITY) {
200	                    Location location = new Location(row, col);
201	                    Animal gazelle = new Gazelle(true, field, location);
202	                    animals.add(gazelle);
